"""One-line summary of the catalogue."""
import json

from shelf import books


def summary():
    return "%d books" % len(books.all_books())


def by_author():
    counts = {}
    for b in books.all_books():
        counts[b["author"]] = counts.get(b["author"], 0) + 1
    return counts


def as_json():
    return json.dumps({"summary": summary(), "by_author": by_author()})

